const got = await tools.exec_command({
  cmd: "sed -n '637p' tome-ashes-urhrok.lua",
  workdir: "/workspace/tome4-chinese-translation",
  yield_time_ms: 10000,
  max_output_tokens: 10000,
  sandbox_permissions: "require_escalated",
  justification: "Allow applying a dynamically exact patch to the one long translation record?"
});
if (got.exit_code !== 0) throw new Error(got.output);
const oldLine = got.output.replace(/\n$/, "");
const matches = oldLine.match(/乌尔洛克/g) || [];
if (matches.length !== 4 || !oldLine.startsWith('t("Our tournaments, run ever since our salvation')) {
  throw new Error(`guard failed: matched ${matches.length} occurrences`);
}
const newLine = oldLine.replaceAll("乌尔洛克", "乌鲁洛克");
const patch = `*** Begin Patch\n*** Update File: /workspace/tome4-chinese-translation/tome-ashes-urhrok.lua\n@@\n-${oldLine}\n+${newLine}\n*** End Patch`;
text(await tools.apply_patch(patch));

const results = await Promise.all([
  tools.exec_command({
    cmd: "python3 -B evidence/quality/repair-window-27-20260924/verify.py",
    workdir: "/workspace/tome4-chinese-translation",
    yield_time_ms: 30000,
    max_output_tokens: 30000,
    sandbox_permissions: "require_escalated",
    justification: "Allow running the task's LuaJIT exact-difference verifier?"
  }),
  tools.exec_command({
    cmd: "python3 -B tools/i18n lint --strict",
    workdir: "/workspace/tome4-chinese-translation",
    yield_time_ms: 30000,
    max_output_tokens: 30000,
    sandbox_permissions: "require_escalated",
    justification: "Allow running strict translation lint with the manifest-configured LuaJIT?"
  })
]);
for (const r of results) text(JSON.stringify({exit_code:r.exit_code, output:r.output}));
